#!/usr/bin/env bash
# build_willeq_pack.sh -- rebuild the shared UI/effects pack `willeq.eqe1`
# from checked-in inputs, deterministically and byte-for-byte.
#
# T398 (board B230b). Before this script the 2.8 MB pack at
# /mnt/projects/EverQuest_ETC1/willeq.eqe1 had no build recipe in the repo,
# so nobody could change one atlas pixel without hand-assembling a shared
# asset that three worktrees read concurrently.
#
# The pack has exactly two input sources and no residue:
#   1. `ui_atlas.bmp` + `ui_atlas.json`, generated by `tools/ui_atlas_builder`
#      (fully procedural -- it opens no file). These become the pack entries
#      `ui_atlas`, `ui_atlas_alpha` (ETC1 alpha companion) and the raw entry
#      `ui_atlas.json`.
#   2. The 64 BMPs checked in under `data/textures/` (creature/detail/particle
#      atlases, the rain/snow/storm sets, software_cursor, tumbleweed, ...).
#
# `eqe1_builder` sorts its collected inputs by full path, so the staging
# directory names below ("atlas" before "textures") fix the entry order.
# T279 recorded the ETC1 encoder as deterministic; the rebuild is verified
# byte-identical by the `PackReproducible` ctest test.
#
# Usage:
#   scripts/build_willeq_pack.sh [--check] [--bin-dir DIR] [--output PATH]
#                                [--sha-file PATH] [--keep-temp]
#
#   --check       Build into a temp file and compare against the pinned
#                 sha256 and the installed pack; do NOT install. Exit 0 only
#                 if all three agree. This is what the ctest test runs.
#   --bin-dir     Directory holding `eqe1_builder` and `ui_atlas_builder`
#                 (default: the first of build/bin, build-gles2/bin that has
#                 both).
#   --output      Destination pack path
#                 (default: /mnt/projects/EverQuest_ETC1/willeq.eqe1).
#   --sha-file    Pinned sha256 of the pack
#                 (default: data/willeq.eqe1.sha256).
#   --keep-temp   Leave the staging/temp directory in place for inspection.
#
# The install is ATOMIC: the pack is written to a temp file in the SAME
# directory as the destination and then `mv`'d over it, so a concurrent slot
# running ctest or the visual gate never reads it half-written.

set -u

REPO_ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"

CHECK_ONLY=0
BIN_DIR=""
OUTPUT="/mnt/projects/EverQuest_ETC1/willeq.eqe1"
SHA_FILE=""
KEEP_TEMP=0

while [ $# -gt 0 ]; do
    case "$1" in
        --check)     CHECK_ONLY=1; shift ;;
        --bin-dir)   BIN_DIR="$2"; shift 2 ;;
        --output)    OUTPUT="$2"; shift 2 ;;
        --sha-file)  SHA_FILE="$2"; shift 2 ;;
        --keep-temp) KEEP_TEMP=1; shift ;;
        -h|--help)   sed -n '2,50p' "${BASH_SOURCE[0]}"; exit 0 ;;
        *) echo "build_willeq_pack.sh: unknown argument '$1'" >&2; exit 2 ;;
    esac
done

[ -n "$SHA_FILE" ] || SHA_FILE="$REPO_ROOT/data/willeq.eqe1.sha256"

if [ -z "$BIN_DIR" ]; then
    for cand in "$REPO_ROOT/build/bin" "$REPO_ROOT/build-gles2/bin"; do
        if [ -x "$cand/eqe1_builder" ] && [ -x "$cand/ui_atlas_builder" ]; then
            BIN_DIR="$cand"
            break
        fi
    done
fi

if [ -z "$BIN_DIR" ]; then
    echo "ERROR: no --bin-dir given and neither build/bin nor build-gles2/bin" >&2
    echo "       holds both eqe1_builder and ui_atlas_builder. Build them first:" >&2
    echo "       cmake --build $REPO_ROOT/build --target eqe1_builder ui_atlas_builder" >&2
    exit 3
fi

for t in eqe1_builder ui_atlas_builder; do
    if [ ! -x "$BIN_DIR/$t" ]; then
        echo "ERROR: $BIN_DIR/$t is missing or not executable" >&2
        exit 3
    fi
done

TEXTURES_DIR="$REPO_ROOT/data/textures"
if [ ! -d "$TEXTURES_DIR" ]; then
    echo "ERROR: input directory $TEXTURES_DIR does not exist" >&2
    exit 3
fi

WORK="$(mktemp -d "${TMPDIR:-/tmp}/willeq_pack.XXXXXXXX")"
cleanup() {
    if [ "$KEEP_TEMP" -eq 1 ]; then
        echo "  (staging kept at $WORK)"
    else
        rm -rf "$WORK"
    fi
}
trap cleanup EXIT

# ── Stage 1: the procedural UI atlas ────────────────────────────────────────
# The staging subdirectory MUST sort before the textures one: eqe1_builder
# sorts every collected input path globally, and the shipped pack has
# ui_atlas at index 0. "atlas" < "textures".
mkdir -p "$WORK/atlas"
if ! "$BIN_DIR/ui_atlas_builder" --output "$WORK/atlas" > "$WORK/ui_atlas.log" 2>&1; then
    echo "ERROR: ui_atlas_builder failed:" >&2
    cat "$WORK/ui_atlas.log" >&2
    exit 4
fi

# ── Stage 2: the checked-in BMP set ─────────────────────────────────────────
# Symlinked rather than copied: eqe1_builder's directory_iterator follows
# symlinks, and copying 64 BMPs on every run buys nothing.
ln -s "$TEXTURES_DIR" "$WORK/textures"

# ── Stage 3: pack ───────────────────────────────────────────────────────────
mkdir -p "$WORK/out"
if ! "$BIN_DIR/eqe1_builder" \
        --bmp-dir "$WORK/atlas" \
        --bmp-dir "$WORK/textures" \
        --output "$WORK/out" \
        --name willeq > "$WORK/pack.log" 2>&1; then
    echo "ERROR: eqe1_builder failed:" >&2
    cat "$WORK/pack.log" >&2
    exit 4
fi

BUILT="$WORK/out/willeq.eqe1"
if [ ! -s "$BUILT" ]; then
    echo "ERROR: eqe1_builder produced no pack at $BUILT" >&2
    cat "$WORK/pack.log" >&2
    exit 4
fi

BUILT_SHA="$(sha256sum "$BUILT" | awk '{print $1}')"
BUILT_SIZE="$(stat -c %s "$BUILT")"

PINNED_SHA=""
if [ -f "$SHA_FILE" ]; then
    PINNED_SHA="$(awk 'NF && $1 !~ /^#/ {print $1; exit}' "$SHA_FILE")"
fi

echo "built:  $BUILT_SHA  ($BUILT_SIZE bytes)"
[ -n "$PINNED_SHA" ] && echo "pinned: $PINNED_SHA  ($SHA_FILE)"

if [ "$CHECK_ONLY" -eq 1 ]; then
    rc=0
    if [ -z "$PINNED_SHA" ]; then
        echo "FAIL: no pinned sha256 at $SHA_FILE" >&2
        rc=1
    elif [ "$BUILT_SHA" != "$PINNED_SHA" ]; then
        echo "FAIL: rebuild does not match the pinned sha256." >&2
        echo "      The pack inputs (data/textures/*.bmp or tools/ui_atlas_builder.cpp)" >&2
        echo "      changed. If that was deliberate, rerun this script without --check" >&2
        echo "      to reinstall the pack and update $SHA_FILE in the SAME commit." >&2
        rc=1
    fi
    if [ ! -f "$OUTPUT" ]; then
        echo "FAIL: installed pack $OUTPUT is missing" >&2
        rc=1
    else
        INSTALLED_SHA="$(sha256sum "$OUTPUT" | awk '{print $1}')"
        echo "shipped: $INSTALLED_SHA  ($OUTPUT)"
        if [ "$INSTALLED_SHA" != "$BUILT_SHA" ]; then
            echo "FAIL: the installed pack differs from the rebuild." >&2
            rc=1
        fi
    fi
    if [ "$rc" -eq 0 ]; then
        echo "PASS: rebuild is byte-identical to the pinned hash and the installed pack."
    fi
    exit "$rc"
fi

# ── Stage 4: atomic install ─────────────────────────────────────────────────
OUT_DIR="$(dirname -- "$OUTPUT")"
if [ ! -d "$OUT_DIR" ]; then
    echo "ERROR: destination directory $OUT_DIR does not exist" >&2
    exit 5
fi

# Temp file in the SAME directory so the rename is atomic (same filesystem).
TMP_OUT="$(mktemp "$OUT_DIR/.willeq.eqe1.XXXXXXXX")"
cp "$BUILT" "$TMP_OUT"
chmod --reference="$OUTPUT" "$TMP_OUT" 2>/dev/null || chmod 0644 "$TMP_OUT"
mv -f "$TMP_OUT" "$OUTPUT"
echo "installed: $OUTPUT ($BUILT_SIZE bytes, sha256 $BUILT_SHA)"

if [ -n "$PINNED_SHA" ] && [ "$PINNED_SHA" != "$BUILT_SHA" ]; then
    echo
    echo "NOTE: $SHA_FILE still pins $PINNED_SHA."
    echo "      Update it to $BUILT_SHA in the same commit as the input change,"
    echo "      or the PackReproducible ctest test will fail."
fi
